begin;
create extension if not exists pgtap with schema extensions;
grant execute on all functions in schema extensions to authenticated,anon;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('22400000-0000-4000-8000-000000000001','delete-student@example.invalid'),('22400000-0000-4000-8000-000000000002','delete-mentor@example.invalid'),('22400000-0000-4000-8000-000000000003','delete-staff@example.invalid');
insert into public.mentor_profiles(user_id,display_name,bio,expertise,languages,state,reviewed_by,reviewed_at,verified_summary,decision_reason,accepting) values('22400000-0000-4000-8000-000000000002','SYNTHETIC private name','SYNTHETIC personal biography',array['essays'],array['en'],'verified','22400000-0000-4000-8000-000000000003',now(),'SYNTHETIC verification summary','SYNTHETIC private decision',true);
insert into public.mentor_services(id,mentor_id,kind,summary,deliverables,turnaround_hours) values('22410000-0000-4000-8000-000000000001','22400000-0000-4000-8000-000000000002','essay','SYNTHETIC essay review','Specific actionable suggestions',48);
insert into public.mentor_student_clearances(student_id,approved_until,guardian_required,reviewed_by,reason) values('22400000-0000-4000-8000-000000000001',now()+interval '30 days',true,'22400000-0000-4000-8000-000000000003','SYNTHETIC school consent fixture');
insert into public.writing_drafts(id,user_id,title,kind,content) values('22420000-0000-4000-8000-000000000001','22400000-0000-4000-8000-000000000001','SYNTHETIC essay','essay','Private essay version');
insert into public.writing_versions(id,draft_id,user_id,version,snapshot,request_id) values('22430000-0000-4000-8000-000000000001','22420000-0000-4000-8000-000000000001','22400000-0000-4000-8000-000000000001',1,'{"title":"SYNTHETIC essay","content":"Private essay version"}',gen_random_uuid());
insert into public.mentor_evidence(id,mentor_id,claim,object_path,mime,byte_size,state) values('22440000-0000-4000-8000-000000000001','22400000-0000-4000-8000-000000000002','SYNTHETIC sensitive proof','22400000-0000-4000-8000-000000000002/22440000-0000-4000-8000-000000000001','application/pdf',32,'reviewed');
insert into public.vault_documents(id,user_id,category,sensitivity,display_name,expires_at) values('22450000-0000-4000-8000-000000000001','22400000-0000-4000-8000-000000000001','transcript','academic','SYNTHETIC transcript',now()+interval '30 days');
insert into public.vault_versions(id,document_id,user_id,sequence,object_path,extension,mime,byte_size,sha256,state,scanner,scanned_at) values('22460000-0000-4000-8000-000000000001','22450000-0000-4000-8000-000000000001','22400000-0000-4000-8000-000000000001',1,'private/student/22400000-0000-4000-8000-000000000001/22450000-0000-4000-8000-000000000001/22460000-0000-4000-8000-000000000001/asset.txt','txt','text/plain',32,repeat('b',64),'available','SYNTHETIC permission fixture only',now());
update public.vault_documents set current_version_id='22460000-0000-4000-8000-000000000001' where id='22450000-0000-4000-8000-000000000001';
create temp table deletion_ids(k text primary key,v uuid);
grant select,insert on deletion_ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','22400000-0000-4000-8000-000000000001',true);
insert into deletion_ids values('request',(public.mentor_command(jsonb_build_object('op','create','service','22410000-0000-4000-8000-000000000001','goal','SYNTHETIC clarity review request','expires',now()+interval '7 days','consent',true,'policy','mentor-consent-v1','items','[{"type":"writing","resource":"22420000-0000-4000-8000-000000000001","version":"22430000-0000-4000-8000-000000000001","download":false}]'::jsonb,'key',gen_random_uuid()))->>'id')::uuid);
insert into deletion_ids select 'grant',id from public.mentor_resource_grants where request_id=(select v from deletion_ids where k='request');
select set_config('request.jwt.claim.sub','22400000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.mentor_command(jsonb_build_object('op','transition','request',(select v from deletion_ids where k='request'),'revision',1,'state','accepted'))$$,'fixture assignment accepted');
select lives_ok($$select public.mentor_command(jsonb_build_object('op','comment','request',(select v from deletion_ids where k='request'),'grant',(select v from deletion_ids where k='grant'),'parent',null,'body','SYNTHETIC useful feedback','anchor',null,'key',gen_random_uuid()))$$,'fixture human feedback persists');
select throws_ok($$select public.mentor_resource((select v from deletion_ids where k='grant'),null)$$,'42501',null,'null operation does not bypass operation scope');
reset role;
select lives_ok($$delete from auth.users where id='22400000-0000-4000-8000-000000000003'$$,'historical reviewer identity does not block staff account deletion');
select lives_ok($$delete from auth.users where id='22400000-0000-4000-8000-000000000002'$$,'mentor Auth deletion succeeds without destroying student-owned feedback');
select is((select state from public.mentor_profiles where user_id='22400000-0000-4000-8000-000000000002'),'revoked','deleted mentor stays a non-public revoked audit reference');
select is((select bio from public.mentor_profiles where user_id='22400000-0000-4000-8000-000000000002'),'','mentor biography is erased');
select is((select verified_summary from public.mentor_profiles where user_id='22400000-0000-4000-8000-000000000002'),'','mentor verification summary is erased');
select is((select decision_reason from public.mentor_profiles where user_id='22400000-0000-4000-8000-000000000002'),'','private decision text is erased');
select ok((select revoked_at is not null from public.mentor_requests limit 1),'Auth deletion revokes live assignments');
select ok((select revoked_at is not null from public.mentor_resource_grants limit 1),'Auth deletion revokes artifact grants');
select ok((select retain_until<=now() from public.mentor_evidence limit 1),'identity evidence is queued for immediate physical retention removal');
select is((select claim from public.mentor_evidence limit 1),'Evidence awaiting retention removal','sensitive evidence claim is redacted without falsely claiming blob deletion');
select is(jsonb_array_length(public.mentor_directory()),0,'deleted mentor is absent from public discovery');
set local role authenticated;
-- Emulate an already-issued but not yet expired JWT after actual Auth deletion.
select set_config('request.jwt.claim.sub','22400000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.mentor_resource((select v from deletion_ids where k='grant'))$$,'42501',null,'stale deleted-mentor JWT cannot retrieve private work');
select throws_ok($$select public.mentor_command('{"op":"apply","name":"Ghost mentor","bio":"Deleted identities cannot return","expertise":["essay"],"languages":["en"],"countries":[],"degrees":[],"timezone":"UTC","capacity":1,"terms":true}')$$,'42501',null,'stale JWT cannot reapply after account deletion');
select throws_ok($$select public.mentor_evidence_access('22440000-0000-4000-8000-000000000001')$$,'42501',null,'stale JWT cannot retrieve expired identity evidence');
select set_config('request.jwt.claim.sub','22400000-0000-4000-8000-000000000001',true);
select is((select body from public.mentor_comments limit 1),'SYNTHETIC useful feedback','student retains delivered feedback after mentor deletion');
select is((select author_id from public.mentor_comments limit 1),'22400000-0000-4000-8000-000000000002'::uuid,'pseudonymous original authorship is retained');
reset role;
select set_config('request.jwt.claim.sub','',true);
select lives_ok($$delete from auth.users where id='22400000-0000-4000-8000-000000000001'$$,'student account deletion still cascades through owned mentoring data');
select is((select count(*)::int from public.mentor_requests),0,'student requests are erased');
select is((select count(*)::int from public.mentor_resource_grants),0,'student consent grants are erased');
select is((select count(*)::int from public.mentor_comments),0,'student-owned feedback is erased with student account');
select is((select count(*)::int from public.writing_drafts),0,'earlier Writing ownership deletion still works');
select * from finish();
rollback;
